/**
 * Shared definition of the admin SPA's build environment.
 *
 * `admin/.env.production` holds the two values the admin cannot derive: the Cognito user
 * pool ID and app client ID. Both are generated by AWS at deploy time, so neither can
 * come from `site.config.json` — everything else the admin once read from this file
 * (hosted-UI domain, redirect URI) is now derived in `admin/src/lib/site-config.ts`.
 *
 * Used by two scripts with deliberately different requirements:
 *
 *   generate-admin-env.js  needs AWS credentials; run after a deploy
 *   check-admin-env.js     needs nothing; runs in CI before the admin build
 *
 * The split matters because the CI job that builds the admin has no AWS credentials by
 * design. See the comment in check-admin-env.js.
 */
import { dirname, join } from "path";
import { fileURLToPath } from "url";

/**
 * Variables the admin build requires, mapped to the CloudFormation export that supplies
 * each one. Exports are looked up by name rather than by reading a named stack, so this
 * does not need to know what the stack is called.
 */
export const REQUIRED_VARS = [
  {
    name: "VITE_COGNITO_USER_POOL_ID",
    export: "AdminUserPoolId",
    description: "Cognito user pool the admin authenticates against",
  },
  {
    name: "VITE_COGNITO_CLIENT_ID",
    export: "AdminUserPoolClientId",
    description: "Cognito app client used for the hosted-UI flow",
  },
];

/**
 * Resolved from this module's location, not the working directory: `check-admin-env.js`
 * runs as admin's `prebuild`, where the working directory is `admin/`.
 */
export const ENV_PATH = join(dirname(fileURLToPath(import.meta.url)), "../admin/.env.production");

/** Path to show in messages — the absolute one is noise in a build log. */
export const ENV_LABEL = "admin/.env.production";

/** Parses a dotenv file into a plain object. Comments and blank lines are ignored. */
export function parseEnv(text) {
  const out = {};
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    out[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
  }
  return out;
}

/**
 * Returns a list of problems with a parsed environment, empty when it is usable.
 *
 * Treats an empty value as missing. That is the failure that actually happened here: a
 * mistyped key name meant the real variable was never set, the build succeeded, and the
 * deployed admin threw "Both UserPoolId and ClientId are required" on load — a white
 * screen with no indication of the cause.
 */
export function validateEnv(env) {
  const problems = [];
  for (const { name, description } of REQUIRED_VARS) {
    const value = env[name];
    if (value === undefined) {
      problems.push(`${name} is missing (${description})`);
    } else if (value === "") {
      problems.push(`${name} is empty (${description})`);
    }
  }
  // A key that looks like a typo of a required one is worth naming explicitly, since
  // that is precisely how this broke before.
  for (const key of Object.keys(env)) {
    if (REQUIRED_VARS.some((v) => v.name === key)) continue;
    const near = REQUIRED_VARS.find((v) => v.name.includes(key) || key.includes(v.name.slice(1)));
    if (near) {
      problems.push(`${key} looks like a misspelling of ${near.name}`);
    }
  }
  return problems;
}

/** Renders the environment file. Kept here so both scripts agree on the format. */
export function renderEnv(values) {
  const lines = [
    "# Generated by scripts/generate-admin-env.js from CloudFormation exports.",
    "# Do not edit by hand: run `make admin-env` after a deploy instead.",
    "#",
    "# These are the only two values the admin cannot derive from site.config.json.",
    "# They are public identifiers, embedded in the shipped bundle and visible to any",
    "# visitor, so they are not secrets — but they are deployment-specific.",
    "",
    ...REQUIRED_VARS.map(({ name }) => `${name}=${values[name]}`),
    "",
  ];
  return lines.join("\n");
}
